@layer theme {
	:root {
		@variant light {
			--color-background: #ffffff;
			--color-foreground: #262626;
			--color-card: #ffffff;
			--color-card-foreground: #262626;
			/*
			 * A surface that sits ABOVE `muted`, in both themes.
			 *
			 * `card` cannot do this job: it is the same white as `background` in
			 * light and *darker* than `muted` in dark, so a control painted on it
			 * inside a muted track reads as raised in one theme and sunken in the
			 * other. Nothing else in the neutral ramp is lighter than `muted` in
			 * dark either. `Tabs`' selected capsule is what this exists for.
			 */
			--color-elevated: #ffffff;
			--color-elevated-foreground: #262626;
			--color-popover: #ffffff;
			--color-popover-foreground: #262626;

			--color-primary: #262626;
			--color-primary-foreground: #fafafa;
			--color-secondary: #f1f1f1;
			--color-secondary-foreground: #262626;
			--color-tertiary: #f8f8f8;
			--color-tertiary-foreground: #404040;

			--color-muted: #f1f1f1;
			--color-muted-foreground: #6f6f6f;
			--color-accent: #f1f1f1;
			--color-accent-foreground: #262626;

			--color-danger: #ef4444;
			--color-danger-foreground: #ffffff;
			--color-danger-soft: #fef2f2;
			--color-danger-soft-foreground: #b91c1c;

			--color-success: #10b981;
			--color-success-foreground: #ffffff;
			--color-success-soft: #ecfdf5;
			--color-success-soft-foreground: #047857;
			--color-warning: #f59e0b;
			--color-warning-foreground: #1c1917;
			--color-warning-soft: #fffbeb;
			--color-warning-soft-foreground: #b45309;
			--color-info: #3b82f6;
			--color-info-foreground: #ffffff;
			--color-info-soft: #eff6ff;
			--color-info-soft-foreground: #1d4ed8;

			--color-border: #e6e6e6;
			--color-input: #dcdcdc;
			--color-ring: #a1a1a1;

			/*
			 * The scrim a BottomSheet draws over the app it covers.
			 *
			 * A surface token with no `-foreground`: nothing is ever drawn on it,
			 * and the sheet in front carries its own. It is not `bg-black/50` at a
			 * call site because a pure-black scrim over a near-black dark theme is
			 * nearly invisible — the two variants below differ on purpose, and the
			 * alpha lives with the colour so a caller never has to restate it.
			 */
			--color-overlay: rgba(0, 0, 0, 0.45);
		}

		@variant dark {
			--color-background: #0a0a0a;
			--color-foreground: #f5f5f5;
			--color-card: #141414;
			--color-card-foreground: #f5f5f5;
			--color-elevated: #3a3a3a;
			--color-elevated-foreground: #f5f5f5;
			--color-popover: #141414;
			--color-popover-foreground: #f5f5f5;

			--color-primary: #f5f5f5;
			--color-primary-foreground: #262626;
			--color-secondary: #262626;
			--color-secondary-foreground: #f5f5f5;
			--color-tertiary: #1c1c1c;
			--color-tertiary-foreground: #d4d4d4;

			--color-muted: #262626;
			--color-muted-foreground: #a1a1a1;
			--color-accent: #262626;
			--color-accent-foreground: #f5f5f5;

			--color-danger: #f05252;
			--color-danger-foreground: #ffffff;
			--color-danger-soft: #2a1416;
			--color-danger-soft-foreground: #f87171;

			--color-success: #10b981;
			--color-success-foreground: #05231a;
			--color-success-soft: #0c231c;
			--color-success-soft-foreground: #34d399;
			--color-warning: #f59e0b;
			--color-warning-foreground: #1c1917;
			--color-warning-soft: #2a1f0c;
			--color-warning-soft-foreground: #fbbf24;
			--color-info: #3b82f6;
			--color-info-foreground: #ffffff;
			--color-info-soft: #111f33;
			--color-info-soft-foreground: #60a5fa;

			--color-border: #2b2b2b;
			--color-input: #333333;
			--color-ring: #737373;
			--color-overlay: rgba(0, 0, 0, 0.65);
		}
	}
}

@layer theme {
	:root {
		/*
		 * The one font family this package names.
		 *
		 * Tailwind's default `--font-mono` is a comma-separated web stack, and
		 * React Native's `fontFamily` takes a single family name with no fallback
		 * list — the whole string would resolve to nothing and quietly fall back
		 * to the system sans, which is the opposite of what `Text.Code` is for.
		 *
		 * No single name works on both platforms: iOS has Menlo and not
		 * `monospace`, Android the reverse. Both ship with the OS, so nothing has
		 * to be loaded through `expo-font` and a consuming app needs no plugin.
		 *
		 * This cannot live in `tokens.css`: platform selection needs `@variant`,
		 * and `@theme {}` accepts custom properties only. It also needs the
		 * `noDuplicateCustomProperties` exemption `biome.jsonc` scopes to this
		 * file — the same one `light` and `dark` already rely on.
		 */
		@variant ios {
			--font-mono: "Menlo";
		}

		@variant android {
			--font-mono: "monospace";
		}
	}
}

@theme {
	--radius-xs: 6px;
	--radius-sm: 8px;
	--radius-md: 10px;
	--radius-lg: 12px;
	--radius-xl: 16px;
	--radius-2xl: 20px;
	--radius-full: 9999px;

	--text-xs: 12px;
	--text-sm: 14px;
	--text-base: 16px;
	--text-lg: 18px;
	--text-xl: 20px;
	--text-2xl: 24px;
	--text-3xl: 30px;

	/* Button heights, and the square footprint of an icon-only one. */
	--spacing-button-sm: 36px;
	--spacing-button-md: 44px;
	--spacing-button-lg: 52px;

	/* Label type scale, one step paired with each button height above. */
	--text-button-sm: 14px;
	--text-button-md: 16px;
	--text-button-lg: 18px;

	/*
	 * Field heights, and the type scale paired step-for-step with them.
	 *
	 * A scale of its own rather than `--spacing-button-*`, even though the
	 * numbers agree today: a control that borrowed the button's would retune
	 * silently whenever the button's did.
	 */
	--spacing-input-sm: 36px;
	--spacing-input-md: 44px;
	--spacing-input-lg: 52px;

	--text-input-sm: 14px;
	--text-input-md: 16px;
	--text-input-lg: 18px;

	/*
	 * The icon scale, shared by `Icon` and `Spinner` so a named size means the
	 * same edge length in both and one can replace the other without the
	 * layout moving. `size-icon-md`.
	 *
	 * A component's own size axis indexes into this scale rather than restating
	 * a number: a button's sm/md/lg icon is icon-sm/md/lg.
	 *
	 * It sizes more than glyphs. A `Checkbox`'s square reads it too, two steps
	 * above the tick it holds, rather than minting a scale that would have to be
	 * retuned in step with this one forever.
	 */
	--spacing-icon-xs: 14px;
	--spacing-icon-sm: 16px;
	--spacing-icon-md: 18px;
	--spacing-icon-lg: 20px;
	--spacing-icon-xl: 24px;
	--spacing-icon-2xl: 32px;

	/*
	 * Screen chrome. `h-navbar-row` is the navbar's control row on its own —
	 * the safe-area band above it is padding, not part of this number, so one
	 * value holds across every device.
	 *
	 * `px-screen-gutter` is the horizontal gutter `Screen.Header`,
	 * `Screen.Navbar` and a screen's own content all line up against. It is one
	 * token rather than three `px-5`s so a change moves every edge together.
	 *
	 * The footer's padding is deliberately NOT here — see `screen.variants.ts`.
	 */
	--spacing-navbar-row: 56px;
	--spacing-screen-gutter: 20px;
}

/**
 * Names of the semantic size tokens defined in `tokens.css`.
 *
 * These exist so `cn()` can teach tailwind-merge about them. Without that,
 * `h-button-md` is an unrecognised utility and twMerge will not drop it when a
 * caller passes `h-12` — both survive and the override silently stops working.
 * {@link ../lib/cn} registers every name here, and a test asserts this list
 * still matches `tokens.css`.
 *
 * Values live in the CSS, not here. A component references a token by writing
 * the class out in full (`size-icon-md`) — Tailwind scans source text, so a
 * name assembled at runtime would never be compiled.
 */

/** Suffixes in the `--spacing-*` namespace: `h-button-md`, `w-button-md`. */
export const BUTTON_SIZE_TOKENS = ["button-sm", "button-md", "button-lg"] as const;

/** Suffixes in the `--spacing-*` namespace: `size-icon-md`. */
export const ICON_SIZE_TOKENS = ["icon-xs", "icon-sm", "icon-md", "icon-lg", "icon-xl", "icon-2xl"] as const;

/**
 * Suffixes in the `--spacing-*` namespace: `h-navbar-row`, `px-screen-gutter`.
 *
 * Not a scale — two independent measurements of a screen's chrome — so unlike
 * the icon and button tokens their order carries no meaning.
 */
export const SCREEN_SIZE_TOKENS = ["navbar-row", "screen-gutter"] as const;

/**
 * Suffixes in the `--spacing-*` namespace: `h-input-md`, `min-h-input-md`.
 *
 * Read on two axes, unlike the button's: a single-line field takes the height
 * as a fixed one and a multiline field takes it as a floor, so both `h-` and
 * `min-h-` have to be recognised.
 */
export const INPUT_SIZE_TOKENS = ["input-sm", "input-md", "input-lg"] as const;

/** Suffixes in the `--text-*` namespace: `text-button-md`. */
export const BUTTON_TEXT_TOKENS = ["button-sm", "button-md", "button-lg"] as const;

/** Suffixes in the `--text-*` namespace: `text-input-md`. */
export const INPUT_TEXT_TOKENS = ["input-sm", "input-md", "input-lg"] as const;

/**
 * The tailwind-merge extension both mergers in this package are built from.
 *
 * There are two, and they are easy to forget: `cn()` merges a caller's
 * className, and `tv()` merges slots and variants using a tailwind-merge
 * instance of its own. Extending only one leaves the other treating
 * `text-button-md` as an unrecognised utility — which is how a size token ends
 * up colliding with a colour and silently dropping it. One config, read by
 * `lib/cn.ts` and `lib/tv.ts`, so they cannot drift apart.
 */
export const TW_MERGE_CONFIG = {
	extend: {
		theme: {
			spacing: [...BUTTON_SIZE_TOKENS, ...ICON_SIZE_TOKENS, ...INPUT_SIZE_TOKENS, ...SCREEN_SIZE_TOKENS],
			text: [...BUTTON_TEXT_TOKENS, ...INPUT_TEXT_TOKENS],
		},
	},
} as const;
